mapper.select:
SELECT u.id, u.nickname, u.avatar, u.phone, u.gender, u.identity, u.province, u.city, u.district, u.school, u.grade, u.target_major AS targetMajor, u.member_level AS memberLevel, u.member_expire_time AS memberExpireTime, u.created_at AS createdAt, IFNULL(s.total_practice, 0) AS totalPractice, s.last_practice_at AS lastPracticeAt, CASE WHEN IFNULL(s.total_practice, 0) = 0 THEN 0 ELSE ROUND(s.correct_count * 100.0 / s.total_practice) END AS correctRate FROM t_user u LEFT JOIN ( SELECT user_id, COUNT(*) AS total_practice, SUM(CASE WHEN is_correct = 1 THEN 1 ELSE 0 END) AS correct_count, MAX(created_at) AS last_practice_at FROM t_practice_record GROUP BY user_id ) s ON s.user_id = u.id WHERE u.deleted = 0
AND (u.nickname LIKE CONCAT('%', #{q.keyword}, '%') OR u.phone LIKE CONCAT('%', #{q.keyword}, '%'))
AND u.identity = #{q.identity}
AND u.member_level = #{q.memberLevel}
AND u.province = #{q.province}
AND u.school LIKE CONCAT('%', #{q.school}, '%')
ORDER BY u.id DESC
